    async downloadImage() {
      try {
        GUI.disableSideBar(true);
        this.state.downloading = true;
        if (['jpg', 'png', 'svg'].includes(this.format)) {
          await this.imageToDataURL({ src: this.state.url, type: `image/${this.format}` });
