  watch: {
    ready: {
      handler(bool) {
        GUI.setLoadingContent(!bool);
      },
      immediate: true,
    }
  },

  beforeDestroy() {
    if (this.state.url && 'POST' === ApplicationState.project.state.ows_method) {
      URL.revokeObjectURL(this.state.url);
    }
  },

